function tkWanted(name){ const n = String(name || ''); if (/\/Saved\/[^/]+\.csv$/i.test(n) || /^[^/]+\.csv$/i.test(n)) return 'csv'; if (/Saved Places\.json$/i.test(n)) return 'json'; return ''; }
