const TK_ABSORB_RATIO = 3, TK_BIG_P = 100000, TK_ATTACH_KM = 45, TK_ISLAND_MAX_R = 60, TK_SMALL_N = 5;
const TK_NEAR_KM = 60, TK_PICK_MAX = 15; /* r84-3 (ق١٠-٢٠-٠٢): الجوار بالفجوة بين حافّتي النطاقين لا بين المركزين (بالما–ماهون ١٣٠ كم مركزًا · ٤٠ حافّةً) · القائمة حتى ١٥ مدينة */
